1	package shadow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"math/big"
9		"reflect"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// errTrailingJSON 表示第一个完整 JSON 值之后还存在第二个值或其他非空白文本。
16	var errTrailingJSON = errors.New("shadow: trailing content after JSON value")
17	
18	// DiffEntry 描述期望配置与上报配置之间的一处差异。
19	type DiffEntry struct {
20		// Path 是差异位置的 JSON Pointer（RFC 6901），如 "/wifi/ssid"。
21		Path string
22		// DesiredExists 表示期望配置在该路径是否存在值。
23		DesiredExists bool
24		// ReportedExists 表示上报配置在该路径是否存在值。
25		ReportedExists bool
26		// Desired 是期望配置在该路径的原始 JSON，不存在时为 nil。
27		Desired json.RawMessage
28		// Reported 是上报配置在该路径的原始 JSON，不存在时为 nil。
29		Reported json.RawMessage
30		// Since 是该路径的差异首次出现的时间。
31		Since time.Time
32	}
33	
34	// computeDiff 计算两份 JSON 对象配置之间的差异，按路径字典序返回。
35	// desired 与 reported 必须都是 JSON 对象（调用方保证）。
36	func computeDiff(desired, reported json.RawMessage) []DiffEntry {
37		dObj, _ := decodeObject(desired)
38		rObj, _ := decodeObject(reported)
39		var out []DiffEntry
40		walkObject("", dObj, rObj, &out)
41		sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
42		return out
43	}
44	
45	// walkObject 递归比较两个对象。prefix 是当前路径前缀。
46	func walkObject(prefix string, d, r map[string]json.RawMessage, out *[]DiffEntry) {
47		keys := make([]string, 0, len(d)+len(r))
48		seen := make(map[string]bool, len(d)+len(r))
49		for k := range d {
50			seen[k] = true
51			keys = append(keys, k)
52		}
53		for k := range r {
54			if !seen[k] {
55				keys = append(keys, k)
56			}
57		}
58		for _, k := range keys {
59			path := prefix + "/" + escapePointer(k)
60			dv, dok := d[k]
61			rv, rok := r[k]
62			switch {
63			case dok && !rok:
64				// 一侧整个字段不存在：只在该字段处列一条差异，不再下钻。
65				*out = append(*out, DiffEntry{Path: path, DesiredExists: true, Desired: cloneRaw(dv)})
66			case !dok && rok:
67				*out = append(*out, DiffEntry{Path: path, ReportedExists: true, Reported: cloneRaw(rv)})
68			default:
69				dSub, dIsObj := asObject(dv)
70				rSub, rIsObj := asObject(rv)
71				if dIsObj && rIsObj {
72					// 双方均为对象：逐层比较。
73					walkObject(path, dSub, rSub, out)
74				} else if !rawEqual(dv, rv) {
75					// 其他值（含数组、null）按整体比较，数组不拆分。
76					*out = append(*out, DiffEntry{
77						Path:           path,
78						DesiredExists:  true,
79						ReportedExists: true,
80						Desired:        cloneRaw(dv),
81						Reported:       cloneRaw(rv),
82					})
83				}
84			}
85		}
86	}
87	
88	// escapePointer 按 RFC 6901 转义路径段。
89	func escapePointer(s string) string {
90		s = strings.ReplaceAll(s, "~", "~0")
91		s = strings.ReplaceAll(s, "/", "~1")
92		return s
93	}
94	
95	// decodeObject 把 raw 解析为 JSON 对象；raw 不是单一 JSON 对象时返回 false。
96	// 对象前后允许 JSON 标准空白（空格、制表符、回车、换行）；对象结束后若还有
97	// 第二个 JSON 值或其他非空白文本，同样视为非法。字符串字段中的花括号属于
98	// 字段值，不影响判定。
99	func decodeObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
100		trimmed := bytes.TrimLeft(raw, " \t\r\n")
101		if len(trimmed) == 0 || trimmed[0] != '{' {
102			return nil, false
103		}
104		var obj map[string]json.RawMessage
105		dec := json.NewDecoder(bytes.NewReader(raw))
106		if err := dec.Decode(&obj); err != nil {
107			return nil, false
108		}
109		if err := assertSingleValue(dec); err != nil {
110			return nil, false
111		}
112		if obj == nil { // "null" 已通过首字符排除，这里防御性处理
113			obj = map[string]json.RawMessage{}
114		}
115		return obj, true
116	}
117	
118	func asObject(raw json.RawMessage) (map[string]json.RawMessage, bool) {
119		return decodeObject(raw)
120	}
121	
122	// assertSingleValue 确认解码器读完一个完整 JSON 值后只剩 JSON 空白：
123	// 第二个值解码成功（err == nil）或尾随文本无法解析（任何非 io.EOF 错误）
124	// 都表示输入不是单一 JSON 值，必须拒绝。
125	func assertSingleValue(dec *json.Decoder) error {
126		var extra json.RawMessage
127		if err := dec.Decode(&extra); err != io.EOF {
128			return errTrailingJSON
129		}
130		return nil
131	}
132	
133	// validateConfig 校验配置必须是合法的 JSON 对象，并返回独立副本。
134	func validateConfig(raw json.RawMessage) (json.RawMessage, error) {
135		if _, ok := decodeObject(raw); !ok {
136			return nil, ErrInvalidConfig
137		}
138		return cloneRaw(raw), nil
139	}
140	
141	// rawEqual 比较两份 JSON 值是否语义相等：忽略对象字段顺序，
142	// 数字按数值比较（1 与 1.0 相等），其余按类型与值比较。
143	func rawEqual(a, b json.RawMessage) bool {
144		av, err := decodeValue(a)
145		if err != nil {
146			return false
147		}
148		bv, err := decodeValue(b)
149		if err != nil {
150			return false
151		}
152		return jsonDeepEqual(av, bv)
153	}
154	
155	func decodeValue(raw json.RawMessage) (any, error) {
156		dec := json.NewDecoder(bytes.NewReader(raw))
157		dec.UseNumber()
158		var v any
159		if err := dec.Decode(&v); err != nil {
160			return nil, err
161		}
162		if err := assertSingleValue(dec); err != nil {
163			return nil, err
164		}
165		return v, nil
166	}
167	
168	func jsonDeepEqual(a, b any) bool {
169		switch av := a.(type) {
170		case map[string]any:
171			bv, ok := b.(map[string]any)
172			if !ok || len(av) != len(bv) {
173				return false
174			}
175			for k, va := range av {
176				vb, ok := bv[k]
177				if !ok || !jsonDeepEqual(va, vb) {
178					return false
179				}
180			}
181			return true
182		case []any:
183			bv, ok := b.([]any)
184			if !ok || len(av) != len(bv) {
185				return false
186			}
187			for i := range av {
188				if !jsonDeepEqual(av[i], bv[i]) {
189					return false
190				}
191			}
192			return true
193		case json.Number:
194			bv, ok := b.(json.Number)
195			if !ok {
196				return false
197			}
198			return numberEqual(av, bv)
199		default:
200			return reflect.DeepEqual(a, b)
201		}
202	}
203	
204	func numberEqual(a, b json.Number) bool {
205		if a.String() == b.String() {
206			return true
207		}
208		ra, okA := new(big.Rat).SetString(a.String())
209		rb, okB := new(big.Rat).SetString(b.String())
210		if okA && okB {
211			return ra.Cmp(rb) == 0
212		}
213		return false
214	}
215	
216	func cloneRaw(raw json.RawMessage) json.RawMessage {
217		if raw == nil {
218			return nil
219		}
220		out := make(json.RawMessage, len(raw))
221		copy(out, raw)
222		return out
223	}
