1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
42		RequestID string
43		// Before 是修改前的完整期望配置。
44		Before json.RawMessage
45		// After 是修改后的完整期望配置。
46		After json.RawMessage
47	}
48	
49	// deviceState 是单台设备的内部状态。
50	type deviceState struct {
51		Version        string
52		Online         bool
53		Revision       uint64
54		Desired        json.RawMessage
55		Reported       json.RawMessage
56		LastSeq        uint64
57		LastReportTime time.Time
58		// DiffSince 记录每条差异路径首次出现的时间。
59		DiffSince map[string]time.Time
60		Audit     []AuditRecord
61	}
62	
63	// validateLastReport 校验设备记录的最近上报侧必须自洽，只能表示以下两种
64	// 形态之一：
65	//   - 已经登记但从未上报：LastSeq 为 0，此时上报时间必须为零值、上报配置
66	//     必须是空 JSON 对象（按 JSON 内容判断，允许合法空白）、设备必须离线；
67	//     期望侧可以已经修改过（期望配置非空、存在审计或配置差异都合法）。
68	//   - 已有一次有效上报：LastSeq 为正整数，此时必须保存非零的上报时间；
69	//     上报配置允许是空对象，设备也允许随后被标记为离线。
70	//
71	// 两种形态的当前版本都必须非空。序号允许跳号。校验只检查记录自身的一致性，
72	// 不补时间、不改序号、不清空上报配置、不替换版本。
73	func (d *deviceState) validateLastReport() error {
74		if d.Version == "" {
75			return errors.New("version is empty")
76		}
77		if d.LastSeq == 0 {
78			if !d.LastReportTime.IsZero() {
79				return errors.New("never-reported device has a last report time")
80			}
81			reported, ok := decodeObject(d.Reported)
82			if !ok {
83				// 理论上 restore 已用 decodeObject 校验过，这里防御性处理。
84				return errors.New("never-reported device reported config invalid")
85			}
86			if len(reported) != 0 {
87				return errors.New("never-reported device has non-empty reported config")
88			}
89			if d.Online {
90				return errors.New("never-reported device is online")
91			}
92			return nil
93		}
94		if d.LastReportTime.IsZero() {
95			return errors.New("reported device has zero last report time")
96		}
97		return nil
98	}
99	
100	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
101	func (d *deviceState) refreshDiff(t time.Time) {
102		entries := computeDiff(d.Desired, d.Reported)
103		next := make(map[string]time.Time, len(entries))
104		for _, e := range entries {
105			if since, ok := d.DiffSince[e.Path]; ok {
106				next[e.Path] = since
107			} else {
108				next[e.Path] = t
109			}
110		}
111		d.DiffSince = next
112	}
113	
114	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
115	// Store 可安全并发使用。
116	type Store struct {
117		mu        sync.Mutex
118		dir       string
119		closed    bool
120		devices   map[string]*deviceState
121		versions  map[string]*versionState
122		campaigns map[string]*campaignState
123		batches   map[string]*batchRequestState
124	}
125	
126	// Open 打开（必要时创建）位于 dir 的本地影子存储。
127	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
128	func Open(dir string) (*Store, error) {
129		if err := os.MkdirAll(dir, 0o755); err != nil {
130			return nil, fmt.Errorf("shadow: create store dir: %w", err)
131		}
132		s := &Store{
133			dir:       dir,
134			devices:   map[string]*deviceState{},
135			versions:  map[string]*versionState{},
136			campaigns: map[string]*campaignState{},
137			batches:   map[string]*batchRequestState{},
138		}
139		data, err := os.ReadFile(s.filePath())
140		if errors.Is(err, fs.ErrNotExist) {
141			return s, nil
142		}
143		if err != nil {
144			return nil, fmt.Errorf("shadow: read store: %w", err)
145		}
146		if err := s.restore(data); err != nil {
147			return nil, err
148		}
149		return s, nil
150	}
151	
152	// Close 关闭存储。关闭后的操作返回 ErrClosed。
153	func (s *Store) Close() error {
154		s.mu.Lock()
155		defer s.mu.Unlock()
156		if s.closed {
157			return ErrClosed
158		}
159		s.closed = true
160		return nil
161	}
162	
163	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
164	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
165	func (s *Store) Register(deviceID, version string) error {
166		s.mu.Lock()
167		defer s.mu.Unlock()
168		if err := s.checkOpen(); err != nil {
169			return err
170		}
171		if deviceID == "" {
172			return ErrInvalidDeviceID
173		}
174		if version == "" {
175			return ErrInvalidVersion
176		}
177		if _, ok := s.devices[deviceID]; ok {
178			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
179		}
180		return s.commit(func() error {
181			s.devices[deviceID] = &deviceState{
182				Version:   version,
183				Desired:   json.RawMessage(`{}`),
184				Reported:  json.RawMessage(`{}`),
185				DiffSince: map[string]time.Time{},
186			}
187			return nil
188		})
189	}
190	
191	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
192	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
193	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
194	//
195	// 配置校验、修订号判断、配置替换、审计与差异时间更新与批量修改共用同一
196	// 实现（checkDesiredMeta/checkDesiredRevision/applyDesired），仅校验次序
197	// 与错误消息格式保持各自既有形式。
198	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		if err := s.checkOpen(); err != nil {
202			return 0, err
203		}
204		d, err := s.lookup(deviceID)
205		if err != nil {
206			return 0, err
207		}
208		if err := checkDesiredMeta(operator, at); err != nil {
209			return 0, err
210		}
211		cfg, err := validateConfig(config)
212		if err != nil {
213			return 0, err
214		}
215		if err := checkDesiredRevision(d, deviceID, revision); err != nil {
216			return 0, desiredSingleError(err.(errDesiredRevision))
217		}
218		var newRevision uint64
219		err = s.commit(func() error {
220			newRevision = applyDesired(d, deviceID, operator, at, "", cfg)
221			return nil
222		})
223		if err != nil {
224			return 0, err
225		}
226		return newRevision, nil
227	}
228	
229	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
230	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
231	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
232	//
233	// 校验、序号判断与影子写入规则与安装/回滚成功的附带上报共用同一实现
234	// （checkReport/applyReport），仅错误类别保持各自公开的哨兵不变。
235	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
236		s.mu.Lock()
237		defer s.mu.Unlock()
238		if err := s.checkOpen(); err != nil {
239			return err
240		}
241		d, err := s.lookup(deviceID)
242		if err != nil {
243			return err
244		}
245		in := reportInput{DeviceID: deviceID, Seq: seq, At: at, Version: version, Config: config}
246		cfg, verdict, err := checkReport(d, in, "")
247		if err != nil {
248			return reportPlainError(err.(errBadReport))
249		}
250		if verdict == reportDuplicate {
251			// 重复上报：成功返回，不写入影子，也不触发持久化。
252			return nil
253		}
254		return s.commit(func() error {
255			applyReport(d, in, cfg, verdict, at)
256			return nil
257		})
258	}
259	
260	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
261	func (s *Store) SetOffline(deviceID string) error {
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		if err := s.checkOpen(); err != nil {
265			return err
266		}
267		d, err := s.lookup(deviceID)
268		if err != nil {
269			return err
270		}
271		return s.commit(func() error {
272			d.Online = false
273			return nil
274		})
275	}
276	
277	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
278	// 调用方修改不影响已保存的记录。
279	func (s *Store) Get(deviceID string) (View, error) {
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		if err := s.checkOpen(); err != nil {
283			return View{}, err
284		}
285		d, err := s.lookup(deviceID)
286		if err != nil {
287			return View{}, err
288		}
289		return View{
290			DeviceID: deviceID,
291			Version:  d.Version,
292			Online:   d.Online,
293			Revision: d.Revision,
294			Desired:  cloneRaw(d.Desired),
295			Reported: cloneRaw(d.Reported),
296			LastSeq:  d.LastSeq,
297		}, nil
298	}
299	
300	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
301	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
302		s.mu.Lock()
303		defer s.mu.Unlock()
304		if err := s.checkOpen(); err != nil {
305			return nil, err
306		}
307		d, err := s.lookup(deviceID)
308		if err != nil {
309			return nil, err
310		}
311		entries := computeDiff(d.Desired, d.Reported)
312		for i := range entries {
313			entries[i].Since = d.DiffSince[entries[i].Path]
314		}
315		return entries, nil
316	}
317	
318	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
319	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
320		s.mu.Lock()
321		defer s.mu.Unlock()
322		if err := s.checkOpen(); err != nil {
323			return nil, err
324		}
325		d, err := s.lookup(deviceID)
326		if err != nil {
327			return nil, err
328		}
329		out := make([]AuditRecord, len(d.Audit))
330		for i, rec := range d.Audit {
331			out[i] = rec
332			out[i].Before = cloneRaw(rec.Before)
333			out[i].After = cloneRaw(rec.After)
334		}
335		return out, nil
336	}
337	
338	func (s *Store) checkOpen() error {
339		if s.closed {
340			return ErrClosed
341		}
342		return nil
343	}
344	
345	func (s *Store) lookup(deviceID string) (*deviceState, error) {
346		if deviceID == "" {
347			return nil, ErrInvalidDeviceID
348		}
349		d, ok := s.devices[deviceID]
350		if !ok {
351			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
352		}
353		return d, nil
354	}
355	
356	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
357	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
358	// 调用时必须持有 s.mu。
359	func (s *Store) commit(mutate func() error) error {
360		snapshot, err := s.marshal()
361		if err != nil {
362			return err
363		}
364		if err := mutate(); err != nil {
365			return err
366		}
367		if err := s.persist(); err != nil {
368			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
369			_ = s.restore(snapshot)
370			return err
371		}
372		return nil
373	}
374	
375	func (s *Store) filePath() string {
376		return filepath.Join(s.dir, storeFileName)
377	}
378	
379	// persist 把当前状态原子写入存储文件。
380	func (s *Store) persist() error {
381		data, err := s.marshal()
382		if err != nil {
383			return err
384		}
385		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
386		if err != nil {
387			return fmt.Errorf("shadow: save store: %w", err)
388		}
389		tmpName := tmp.Name()
390		if _, err := tmp.Write(data); err != nil {
391			tmp.Close()
392			os.Remove(tmpName)
393			return fmt.Errorf("shadow: save store: %w", err)
394		}
395		if err := tmp.Sync(); err != nil {
396			tmp.Close()
397			os.Remove(tmpName)
398			return fmt.Errorf("shadow: save store: %w", err)
399		}
400		if err := tmp.Close(); err != nil {
401			os.Remove(tmpName)
402			return fmt.Errorf("shadow: save store: %w", err)
403		}
404		if err := os.Rename(tmpName, s.filePath()); err != nil {
405			os.Remove(tmpName)
406			return fmt.Errorf("shadow: save store: %w", err)
407		}
408		return nil
409	}
410	
411	// diskStore 是存储文件的磁盘格式。
412	type diskStore struct {
413		Format    int                     `json:"format"`
414		Devices   map[string]diskState    `json:"devices"`
415		Versions  map[string]diskVersion  `json:"versions,omitempty"`
416		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
417		Batches   map[string]diskBatch    `json:"batches,omitempty"`
418	}
419	
420	type diskState struct {
421		Version        string               `json:"version"`
422		Online         bool                 `json:"online"`
423		Revision       uint64               `json:"revision"`
424		Desired        json.RawMessage      `json:"desired"`
425		Reported       json.RawMessage      `json:"reported"`
426		LastSeq        uint64               `json:"lastSeq"`
427		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
428		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
429		Audit          []diskAudit          `json:"audit,omitempty"`
430	}
431	
432	type diskAudit struct {
433		Operator  string          `json:"operator"`
434		Time      time.Time       `json:"time"`
435		Revision  uint64          `json:"revision"`
436		RequestID string          `json:"requestId,omitempty"`
437		Before    json.RawMessage `json:"before"`
438		After     json.RawMessage `json:"after"`
439	}
440	
441	func (s *Store) marshal() ([]byte, error) {
442		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
443		for id, d := range s.devices {
444			ds := diskState{
445				Version:        d.Version,
446				Online:         d.Online,
447				Revision:       d.Revision,
448				Desired:        cloneRaw(d.Desired),
449				Reported:       cloneRaw(d.Reported),
450				LastSeq:        d.LastSeq,
451				LastReportTime: d.LastReportTime,
452				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
453			}
454			for p, t := range d.DiffSince {
455				ds.DiffSince[p] = t
456			}
457			for _, rec := range d.Audit {
458				ds.Audit = append(ds.Audit, diskAudit{
459					Operator:  rec.Operator,
460					Time:      rec.Time,
461					Revision:  rec.Revision,
462					RequestID: rec.RequestID,
463					Before:    cloneRaw(rec.Before),
464					After:     cloneRaw(rec.After),
465				})
466			}
467			disk.Devices[id] = ds
468		}
469		disk.Versions = s.marshalVersions()
470		campaigns, err := s.marshalCampaigns()
471		if err != nil {
472			return nil, err
473		}
474		disk.Campaigns = campaigns
475		disk.Batches = s.marshalBatches()
476		data, err := json.Marshal(disk)
477		if err != nil {
478			return nil, fmt.Errorf("shadow: encode store: %w", err)
479		}
480		return data, nil
481	}
482	
483	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
484	// ErrCorruptStorage，绝不按空数据覆盖。
485	func (s *Store) restore(data []byte) error {
486		var disk diskStore
487		if err := json.Unmarshal(data, &disk); err != nil {
488			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
489		}
490		if disk.Format != storeFormat {
491			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
492		}
493		devices := make(map[string]*deviceState, len(disk.Devices))
494		for id, ds := range disk.Devices {
495			if id == "" {
496				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
497			}
498			if _, ok := decodeObject(ds.Desired); !ok {
499				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
500			}
501			if _, ok := decodeObject(ds.Reported); !ok {
502				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
503			}
504			d := &deviceState{
505				Version:        ds.Version,
506				Online:         ds.Online,
507				Revision:       ds.Revision,
508				Desired:        cloneRaw(ds.Desired),
509				Reported:       cloneRaw(ds.Reported),
510				LastSeq:        ds.LastSeq,
511				LastReportTime: ds.LastReportTime,
512				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
513			}
514			if err := d.validateLastReport(); err != nil {
515				return fmt.Errorf("%w: device %s %v", ErrCorruptStorage, id, err)
516			}
517			for p, t := range ds.DiffSince {
518				d.DiffSince[p] = t
519			}
520			for _, da := range ds.Audit {
521				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 {
522					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
523				}
524				if _, ok := decodeObject(da.Before); !ok {
525					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
526				}
527				if _, ok := decodeObject(da.After); !ok {
528					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
529				}
530				d.Audit = append(d.Audit, AuditRecord{
531					DeviceID:  id,
532					Operator:  da.Operator,
533					Time:      da.Time,
534					Revision:  da.Revision,
535					RequestID: da.RequestID,
536					Before:    cloneRaw(da.Before),
537					After:     cloneRaw(da.After),
538				})
539			}
540			// 审计必须能完整解释当前期望配置：修订号从 1 开始逐条连续到当前
541			// 修订号；首条修改前是登记时的空对象，每条修改后等于下一条修改前，
542			// 末条修改后等于当前期望配置。比较沿用配置的 JSON 语义，不要求
543			// 操作时间严格递增。修订号为 0 时审计必须为空、期望必须为空对象。
544			if uint64(len(d.Audit)) != d.Revision {
545				return fmt.Errorf("%w: device %s audit history does not cover revision %d",
546					ErrCorruptStorage, id, d.Revision)
547			}
548			expected := json.RawMessage(`{}`)
549			for i, rec := range d.Audit {
550				if rec.Revision != uint64(i+1) {
551					return fmt.Errorf("%w: device %s audit revision %d out of sequence",
552						ErrCorruptStorage, id, rec.Revision)
553				}
554				if !rawEqual(rec.Before, expected) {
555					return fmt.Errorf("%w: device %s audit revision %d broken chain",
556						ErrCorruptStorage, id, rec.Revision)
557				}
558				expected = rec.After
559			}
560			if !rawEqual(expected, d.Desired) {
561				return fmt.Errorf("%w: device %s desired config not explained by audit",
562					ErrCorruptStorage, id)
563			}
564			// 差异计时记录必须与双方当前配置重新计算出的差异完全一致：
565			// 每条实际差异都要有一条非零的首次出现时间，记录中也不能残留
566			// 当前已经没有差异的路径（父路径不能代替子路径，路径不同即使
567			// 条数相同也不行）。没有差异时允许不保存记录或保存空记录。
568			entries := computeDiff(d.Desired, d.Reported)
569			if len(entries) != len(d.DiffSince) {
570				return fmt.Errorf("%w: device %s diff times do not match current diff paths",
571					ErrCorruptStorage, id)
572			}
573			for _, e := range entries {
574				since, ok := d.DiffSince[e.Path]
575				if !ok {
576					return fmt.Errorf("%w: device %s diff %s missing first-seen time",
577						ErrCorruptStorage, id, e.Path)
578				}
579				if since.IsZero() {
580					return fmt.Errorf("%w: device %s diff %s has zero first-seen time",
581						ErrCorruptStorage, id, e.Path)
582				}
583			}
584			devices[id] = d
585		}
586		s.devices = devices
587		if err := s.restoreVersions(disk.Versions); err != nil {
588			return err
589		}
590		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
591			return err
592		}
593		if err := s.restoreBatches(disk.Batches); err != nil {
594			return err
595		}
596		return nil
597	}
598

file.content:
package shadow

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
	"time"
)

const storeFileName = "shadow-store.json"
const storeFormat = 1

// View 是设备影子当前状态的只读快照。
type View struct {
	DeviceID string
	// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
	Version string
	// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
	Online bool
	// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
	Revision uint64
	// Desired 是期望配置的完整 JSON 对象。
	Desired json.RawMessage
	// Reported 是上报配置的完整 JSON 对象。
	Reported json.RawMessage
	// LastSeq 是最后接受的上报序号。
	LastSeq uint64
}

// AuditRecord 是一次成功修改期望配置的审计记录。
type AuditRecord struct {
	DeviceID string
	Operator string
	Time     time.Time
	// Revision 是本次修改产生的新修订号。
	Revision uint64
	// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
	RequestID string
	// Before 是修改前的完整期望配置。
	Before json.RawMessage
	// After 是修改后的完整期望配置。
	After json.RawMessage
}

// deviceState 是单台设备的内部状态。
type deviceState struct {
	Version        string
	Online         bool
	Revision       uint64
	Desired        json.RawMessage
	Reported       json.RawMessage
	LastSeq        uint64
	LastReportTime time.Time
	// DiffSince 记录每条差异路径首次出现的时间。
	DiffSince map[string]time.Time
	Audit     []AuditRecord
}

// validateLastReport 校验设备记录的最近上报侧必须自洽，只能表示以下两种
// 形态之一：
//   - 已经登记但从未上报：LastSeq 为 0，此时上报时间必须为零值、上报配置
//     必须是空 JSON 对象（按 JSON 内容判断，允许合法空白）、设备必须离线；
//     期望侧可以已经修改过（期望配置非空、存在审计或配置差异都合法）。
//   - 已有一次有效上报：LastSeq 为正整数，此时必须保存非零的上报时间；
//     上报配置允许是空对象，设备也允许随后被标记为离线。
//
// 两种形态的当前版本都必须非空。序号允许跳号。校验只检查记录自身的一致性，
// 不补时间、不改序号、不清空上报配置、不替换版本。
func (d *deviceState) validateLastReport() error {
	if d.Version == "" {
		return errors.New("version is empty")
	}
	if d.LastSeq == 0 {
		if !d.LastReportTime.IsZero() {
			return errors.New("never-reported device has a last report time")
		}
		reported, ok := decodeObject(d.Reported)
		if !ok {
			// 理论上 restore 已用 decodeObject 校验过，这里防御性处理。
			return errors.New("never-reported device reported config invalid")
		}
		if len(reported) != 0 {
			return errors.New("never-reported device has non-empty reported config")
		}
		if d.Online {
			return errors.New("never-reported device is online")
		}
		return nil
	}
	if d.LastReportTime.IsZero() {
		return errors.New("reported device has zero last report time")
	}
	return nil
}

// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
func (d *deviceState) refreshDiff(t time.Time) {
	entries := computeDiff(d.Desired, d.Reported)
	next := make(map[string]time.Time, len(entries))
	for _, e := range entries {
		if since, ok := d.DiffSince[e.Path]; ok {
			next[e.Path] = since
		} else {
			next[e.Path] = t
		}
	}
	d.DiffSince = next
}

// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
// Store 可安全并发使用。
type Store struct {
	mu        sync.Mutex
	dir       string
	closed    bool
	devices   map[string]*deviceState
	versions  map[string]*versionState
	campaigns map[string]*campaignState
	batches   map[string]*batchRequestState
}

// Open 打开（必要时创建）位于 dir 的本地影子存储。
// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
func Open(dir string) (*Store, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("shadow: create store dir: %w", err)
	}
	s := &Store{
		dir:       dir,
		devices:   map[string]*deviceState{},
		versions:  map[string]*versionState{},
		campaigns: map[string]*campaignState{},
		batches:   map[string]*batchRequestState{},
	}
	data, err := os.ReadFile(s.filePath())
	if errors.Is(err, fs.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return nil, fmt.Errorf("shadow: read store: %w", err)
	}
	if err := s.restore(data); err != nil {
		return nil, err
	}
	return s, nil
}

// Close 关闭存储。关闭后的操作返回 ErrClosed。
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return ErrClosed
	}
	s.closed = true
	return nil
}

// Register 登记一台模拟设备。设备标识和初始版本不能为空；
// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
func (s *Store) Register(deviceID, version string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return err
	}
	if deviceID == "" {
		return ErrInvalidDeviceID
	}
	if version == "" {
		return ErrInvalidVersion
	}
	if _, ok := s.devices[deviceID]; ok {
		return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
	}
	return s.commit(func() error {
		s.devices[deviceID] = &deviceState{
			Version:   version,
			Desired:   json.RawMessage(`{}`),
			Reported:  json.RawMessage(`{}`),
			DiffSince: map[string]time.Time{},
		}
		return nil
	})
}

// UpdateDesired 修改设备的期望配置，完整替换旧配置。
// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
//
// 配置校验、修订号判断、配置替换、审计与差异时间更新与批量修改共用同一
// 实现（checkDesiredMeta/checkDesiredRevision/applyDesired），仅校验次序
// 与错误消息格式保持各自既有形式。
func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return 0, err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return 0, err
	}
	if err := checkDesiredMeta(operator, at); err != nil {
		return 0, err
	}
	cfg, err := validateConfig(config)
	if err != nil {
		return 0, err
	}
	if err := checkDesiredRevision(d, deviceID, revision); err != nil {
		return 0, desiredSingleError(err.(errDesiredRevision))
	}
	var newRevision uint64
	err = s.commit(func() error {
		newRevision = applyDesired(d, deviceID, operator, at, "", cfg)
		return nil
	})
	if err != nil {
		return 0, err
	}
	return newRevision, nil
}

// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
//
// 校验、序号判断与影子写入规则与安装/回滚成功的附带上报共用同一实现
// （checkReport/applyReport），仅错误类别保持各自公开的哨兵不变。
func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return err
	}
	in := reportInput{DeviceID: deviceID, Seq: seq, At: at, Version: version, Config: config}
	cfg, verdict, err := checkReport(d, in, "")
	if err != nil {
		return reportPlainError(err.(errBadReport))
	}
	if verdict == reportDuplicate {
		// 重复上报：成功返回，不写入影子，也不触发持久化。
		return nil
	}
	return s.commit(func() error {
		applyReport(d, in, cfg, verdict, at)
		return nil
	})
}

// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
func (s *Store) SetOffline(deviceID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return err
	}
	return s.commit(func() error {
		d.Online = false
		return nil
	})
}

// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
// 调用方修改不影响已保存的记录。
func (s *Store) Get(deviceID string) (View, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return View{}, err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return View{}, err
	}
	return View{
		DeviceID: deviceID,
		Version:  d.Version,
		Online:   d.Online,
		Revision: d.Revision,
		Desired:  cloneRaw(d.Desired),
		Reported: cloneRaw(d.Reported),
		LastSeq:  d.LastSeq,
	}, nil
}

// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return nil, err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return nil, err
	}
	entries := computeDiff(d.Desired, d.Reported)
	for i := range entries {
		entries[i].Since = d.DiffSince[entries[i].Path]
	}
	return entries, nil
}

// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpen(); err != nil {
		return nil, err
	}
	d, err := s.lookup(deviceID)
	if err != nil {
		return nil, err
	}
	out := make([]AuditRecord, len(d.Audit))
	for i, rec := range d.Audit {
		out[i] = rec
		out[i].Before = cloneRaw(rec.Before)
		out[i].After = cloneRaw(rec.After)
	}
	return out, nil
}

func (s *Store) checkOpen() error {
	if s.closed {
		return ErrClosed
	}
	return nil
}

func (s *Store) lookup(deviceID string) (*deviceState, error) {
	if deviceID == "" {
		return nil, ErrInvalidDeviceID
	}
	d, ok := s.devices[deviceID]
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
	}
	return d, nil
}

// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
// 调用时必须持有 s.mu。
func (s *Store) commit(mutate func() error) error {
	snapshot, err := s.marshal()
	if err != nil {
		return err
	}
	if err := mutate(); err != nil {
		return err
	}
	if err := s.persist(); err != nil {
		// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
		_ = s.restore(snapshot)
		return err
	}
	return nil
}

func (s *Store) filePath() string {
	return filepath.Join(s.dir, storeFileName)
}

// persist 把当前状态原子写入存储文件。
func (s *Store) persist() error {
	data, err := s.marshal()
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
	if err != nil {
		return fmt.Errorf("shadow: save store: %w", err)
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return fmt.Errorf("shadow: save store: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return fmt.Errorf("shadow: save store: %w", err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("shadow: save store: %w", err)
	}
	if err := os.Rename(tmpName, s.filePath()); err != nil {
		os.Remove(tmpName)
		return fmt.Errorf("shadow: save store: %w", err)
	}
	return nil
}

// diskStore 是存储文件的磁盘格式。
type diskStore struct {
	Format    int                     `json:"format"`
	Devices   map[string]diskState    `json:"devices"`
	Versions  map[string]diskVersion  `json:"versions,omitempty"`
	Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
	Batches   map[string]diskBatch    `json:"batches,omitempty"`
}

type diskState struct {
	Version        string               `json:"version"`
	Online         bool                 `json:"online"`
	Revision       uint64               `json:"revision"`
	Desired        json.RawMessage      `json:"desired"`
	Reported       json.RawMessage      `json:"reported"`
	LastSeq        uint64               `json:"lastSeq"`
	LastReportTime time.Time            `json:"lastReportTime,omitempty"`
	DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
	Audit          []diskAudit          `json:"audit,omitempty"`
}

type diskAudit struct {
	Operator  string          `json:"operator"`
	Time      time.Time       `json:"time"`
	Revision  uint64          `json:"revision"`
	RequestID string          `json:"requestId,omitempty"`
	Before    json.RawMessage `json:"before"`
	After     json.RawMessage `json:"after"`
}

func (s *Store) marshal() ([]byte, error) {
	disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
	for id, d := range s.devices {
		ds := diskState{
			Version:        d.Version,
			Online:         d.Online,
			Revision:       d.Revision,
			Desired:        cloneRaw(d.Desired),
			Reported:       cloneRaw(d.Reported),
			LastSeq:        d.LastSeq,
			LastReportTime: d.LastReportTime,
			DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
		}
		for p, t := range d.DiffSince {
			ds.DiffSince[p] = t
		}
		for _, rec := range d.Audit {
			ds.Audit = append(ds.Audit, diskAudit{
				Operator:  rec.Operator,
				Time:      rec.Time,
				Revision:  rec.Revision,
				RequestID: rec.RequestID,
				Before:    cloneRaw(rec.Before),
				After:     cloneRaw(rec.After),
			})
		}
		disk.Devices[id] = ds
	}
	disk.Versions = s.marshalVersions()
	campaigns, err := s.marshalCampaigns()
	if err != nil {
		return nil, err
	}
	disk.Campaigns = campaigns
	disk.Batches = s.marshalBatches()
	data, err := json.Marshal(disk)
	if err != nil {
		return nil, fmt.Errorf("shadow: encode store: %w", err)
	}
	return data, nil
}

// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
// ErrCorruptStorage，绝不按空数据覆盖。
func (s *Store) restore(data []byte) error {
	var disk diskStore
	if err := json.Unmarshal(data, &disk); err != nil {
		return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
	}
	if disk.Format != storeFormat {
		return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
	}
	devices := make(map[string]*deviceState, len(disk.Devices))
	for id, ds := range disk.Devices {
		if id == "" {
			return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
		}
		if _, ok := decodeObject(ds.Desired); !ok {
			return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
		}
		if _, ok := decodeObject(ds.Reported); !ok {
			return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
		}
		d := &deviceState{
			Version:        ds.Version,
			Online:         ds.Online,
			Revision:       ds.Revision,
			Desired:        cloneRaw(ds.Desired),
			Reported:       cloneRaw(ds.Reported),
			LastSeq:        ds.LastSeq,
			LastReportTime: ds.LastReportTime,
			DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
		}
		if err := d.validateLastReport(); err != nil {
			return fmt.Errorf("%w: device %s %v", ErrCorruptStorage, id, err)
		}
		for p, t := range ds.DiffSince {
			d.DiffSince[p] = t
		}
		for _, da := range ds.Audit {
			if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 {
				return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
			}
			if _, ok := decodeObject(da.Before); !ok {
				return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
			}
			if _, ok := decodeObject(da.After); !ok {
				return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
			}
			d.Audit = append(d.Audit, AuditRecord{
				DeviceID:  id,
				Operator:  da.Operator,
				Time:      da.Time,
				Revision:  da.Revision,
				RequestID: da.RequestID,
				Before:    cloneRaw(da.Before),
				After:     cloneRaw(da.After),
			})
		}
		// 审计必须能完整解释当前期望配置：修订号从 1 开始逐条连续到当前
		// 修订号；首条修改前是登记时的空对象，每条修改后等于下一条修改前，
		// 末条修改后等于当前期望配置。比较沿用配置的 JSON 语义，不要求
		// 操作时间严格递增。修订号为 0 时审计必须为空、期望必须为空对象。
		if uint64(len(d.Audit)) != d.Revision {
			return fmt.Errorf("%w: device %s audit history does not cover revision %d",
				ErrCorruptStorage, id, d.Revision)
		}
		expected := json.RawMessage(`{}`)
		for i, rec := range d.Audit {
			if rec.Revision != uint64(i+1) {
				return fmt.Errorf("%w: device %s audit revision %d out of sequence",
					ErrCorruptStorage, id, rec.Revision)
			}
			if !rawEqual(rec.Before, expected) {
				return fmt.Errorf("%w: device %s audit revision %d broken chain",
					ErrCorruptStorage, id, rec.Revision)
			}
			expected = rec.After
		}
		if !rawEqual(expected, d.Desired) {
			return fmt.Errorf("%w: device %s desired config not explained by audit",
				ErrCorruptStorage, id)
		}
		// 差异计时记录必须与双方当前配置重新计算出的差异完全一致：
		// 每条实际差异都要有一条非零的首次出现时间，记录中也不能残留
		// 当前已经没有差异的路径（父路径不能代替子路径，路径不同即使
		// 条数相同也不行）。没有差异时允许不保存记录或保存空记录。
		entries := computeDiff(d.Desired, d.Reported)
		if len(entries) != len(d.DiffSince) {
			return fmt.Errorf("%w: device %s diff times do not match current diff paths",
				ErrCorruptStorage, id)
		}
		for _, e := range entries {
			since, ok := d.DiffSince[e.Path]
			if !ok {
				return fmt.Errorf("%w: device %s diff %s missing first-seen time",
					ErrCorruptStorage, id, e.Path)
			}
			if since.IsZero() {
				return fmt.Errorf("%w: device %s diff %s has zero first-seen time",
					ErrCorruptStorage, id, e.Path)
			}
		}
		devices[id] = d
	}
	s.devices = devices
	if err := s.restoreVersions(disk.Versions); err != nil {
		return err
	}
	if err := s.restoreCampaigns(disk.Campaigns); err != nil {
		return err
	}
	if err := s.restoreBatches(disk.Batches); err != nil {
		return err
	}
	return nil
}

