342		}
343		if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
344			t.Fatalf("cleared diff must stay cleared: %+v", diffs)
345		}
346		// 同一路径再次出现差异：必须重新计时，不能沿用消失前的 t1。
347		t4 := base.Add(3 * time.Minute)
348		if _, err := s3.UpdateDesired("dev-1", "op", t4, 2, json.RawMessage(`{"a":3}`)); err != nil {
349			t.Fatal(err)
350		}
351		if err := s3.Close(); err != nil {
