	t.Run("paths follow diff semantics", func(t *testing.T) {
		desired := `{"arr":[1,2],"nul":null,"onlyDesired":{"x":1},"a/b":"d","w~z":"d"}`
		reported := `{"arr":[1,2,3],"onlyReported":5,"a/b":"r","w~z":"r"}`
		want := []string{"/arr", "/a~1b", "/nul", "/onlyDesired", "/onlyReported", "/w~0z"}
		since := map[string]string{}
		for _, p := range want {
			since[p] = at
		}
		doc := fixStore{Format: 1, Devices: map[string]fixState{
			"dev-1": {
				Version:        "1.0",
				Online:         true,
				Revision:       1,
				Desired:        json.RawMessage(desired),
				Reported:       json.RawMessage(reported),
				LastSeq:        1,
				LastReportTime: at,
				DiffSince:      since,
				Audit: []fixAudit{
					{Operator: "op", Time: at, Revision: 1, Before: json.RawMessage(`{}`),
						After: json.RawMessage(desired)},
				},
			},
		}}
		dir, _ := writeFixStore(t, doc)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("escaped/array/null diff paths must open: %v", err)
		}
		defer s.Close()
		diffs, _ := s.Diff("dev-1")
		if len(diffs) != len(want) {
			t.Fatalf("diff count: %+v", diffs)
		}
		for i, p := range want {
			if diffs[i].Path != p {
				t.Fatalf("diff[%d]: want %s got %s", i, p, diffs[i].Path)
			}
			if diffs[i].Since.IsZero() {
				t.Fatalf("diff %s restored zero time", p)
			}
		}
	})

	t.Run("semantic equality needs no record", func(t *testing.T) {
		doc := fixStore{Format: 1, Devices: map[string]fixState{
			"dev-1": {
				Version:  "1.0",
				Online:   true,
				Revision: 1,
				// 字段顺序不同、1 与 1.0 等值：无差异，无计时记录。
				Desired:        json.RawMessage(`{"a":1,"b":{}}`),
				Reported:       json.RawMessage(`{"b":{},"a":1.0}`),
				LastSeq:        1,
				LastReportTime: at,
				Audit: []fixAudit{
					{Operator: "op", Time: at, Revision: 1, Before: json.RawMessage(`{}`),
						After: json.RawMessage(`{"a":1,"b":{}}`)},
				},
			},
		}}
		dir, _ := writeFixStore(t, doc)
		s, err := Open(dir)
		if err != nil {
			t.Fatalf("semantic-equal configs with no diff times must open: %v", err)
		}
		defer s.Close()
		if diffs, _ := s.Diff("dev-1"); len(diffs) != 0 {
			t.Fatalf("unexpected diffs: %+v", diffs)
		}
	})

	t.Run("new empty device and explicit empty record", func(t *testing.T) {
		// 走正常流程登记：双方均为空对象，无差异。
		s, dir := openTemp(t)
		mustRegister(t, s, "dev-1", "1.0")
		if err := s.Close(); err != nil {
			t.Fatal(err)
		}
		s2, err := Open(dir)
		if err != nil {
			t.Fatalf("new empty-object device must reopen: %v", err)
		}
		s2.Close()

		// 手写一份显式保存空计时记录的无差异存储，同样必须能打开。
		dir2 := t.TempDir()
		raw := `{"format":1,"devices":{"dev-1":{"version":"1.0","revision":0,` +
			`"desired":{},"reported":{},"diffSince":{}}}}`
		if err := os.WriteFile(filepath.Join(dir2, storeFileName), []byte(raw), 0o644); err != nil {
			t.Fatal(err)
		}
		s3, err := Open(dir2)
		if err != nil {
			t.Fatalf("empty diffSince record must open: %v", err)
		}
		defer s3.Close()
		if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
			t.Fatalf("unexpected diffs: %+v", diffs)
		}
	})
}

// 实际差异缺时间、残留无差异路径、时间为零、父路径代替子路径、
// 条数相同但路径不同：都必须返回 ErrCorruptStorage 拒绝打开整个存储，
// 且原文件内容保持不变，不补当前时间、不删多余记录、不重写配置。
func TestRestoreDiffSinceCorruptRefused(t *testing.T) {
	cases := map[string]func(fixStore){
		// 实际存在 /wifi/ssid 差异，却完全没有计时记录。
		"missing time record": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince = nil
			doc.Devices["dev-1"] = d
		},
		// 已相等的 /mode 仍残留时间记录。
		"stale record for equal path": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince["/mode"] = "2026-10-02T12:00:00Z"
			doc.Devices["dev-1"] = d
		},
		// 只残留无关路径，实际差异反而没有记录。
		"only stale record": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince = map[string]string{"/mode": "2026-10-02T12:00:00Z"}
			doc.Devices["dev-1"] = d
		},
		// 路径正确但时间为零值。
		"zero first-seen time": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince = map[string]string{"/wifi/ssid": "0001-01-01T00:00:00Z"}
			doc.Devices["dev-1"] = d
		},
		// 父路径 /wifi 的时间不能替代子路径 /wifi/ssid（条数相同）。
		"parent path cannot cover child": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince = map[string]string{"/wifi": "2026-10-02T12:00:00Z"}
			doc.Devices["dev-1"] = d
		},
		// 记录条数与差异条数相同，但路径对不上。
		"same count different path": func(doc fixStore) {
			d := doc.Devices["dev-1"]
			d.DiffSince = map[string]string{"/wifi/chan": "2026-10-02T12:00:00Z"}
			doc.Devices["dev-1"] = d
		},
	}
	for name, mutate := range cases {
		t.Run(name, func(t *testing.T) {
			doc := diffSinceDoc()
			mutate(doc)
			dir, original := writeFixStore(t, doc)
			s, err := Open(dir)
			if err == nil {
				s.Close()
				t.Fatalf("expected ErrCorruptStorage")
			}
			if !errors.Is(err, ErrCorruptStorage) {
				t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
			}
			data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
			if rerr != nil {
				t.Fatal(rerr)
			}
			if string(data) != string(original) {
				t.Fatalf("corrupt file modified on rejected open")
			}
		})
	}

	// 没有差异的设备保存了时间记录同样损坏。
	t.Run("record on device without diffs", func(t *testing.T) {
		doc := fixStore{Format: 1, Devices: map[string]fixState{
			"dev-1": {
				Version:        "1.0",
				Online:         true,
				Revision:       1,
				Desired:        json.RawMessage(`{"a":1}`),
				Reported:       json.RawMessage(`{"a":1}`),
				LastSeq:        1,
				LastReportTime: "2026-10-02T12:00:00Z",
				DiffSince:      map[string]string{"/a": "2026-10-02T12:00:00Z"},
				Audit: []fixAudit{
					{Operator: "op", Time: "2026-10-02T12:00:00Z", Revision: 1,
						Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":1}`)},
				},
			},
		}}
		dir, original := writeFixStore(t, doc)
		if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
			t.Fatalf("stale time on equal device must be refused: %v", err)
		}
		if data, _ := os.ReadFile(filepath.Join(dir, storeFileName)); string(data) != string(original) {
			t.Fatalf("corrupt file modified on rejected open")
		}
	})
}

// 一台设备的计时记录损坏即拒绝打开整个存储，其他设备再正常也不可只跳过坏设备。
func TestRestoreDiffSinceOneBadDeviceRejectsAll(t *testing.T) {
	doc := diffSinceDoc() // dev-1 合法
	doc.Devices["good"] = fixState{
		Version:  "1.0",
		Desired:  json.RawMessage(`{}`),
		Reported: json.RawMessage(`{}`),
	}
	bad := diffSinceDoc().Devices["dev-1"]
	bad.DiffSince = nil // dev-2 有 /wifi/ssid 差异但缺时间记录
	doc.Devices["bad"] = bad
	dir, _ := writeFixStore(t, doc)
	if _, err := Open(dir); !errors.Is(err, ErrCorruptStorage) {
		t.Fatalf("whole store must be refused when one device lacks diff times: %v", err)
	}
}

// 跨关闭重开的计时生命周期：同一路径持续不同保留原时间；差异消失后再次出现
// 才重新计时，且恢复出的计时记录与正常流程产生的记录行为一致。
func TestRestoreDiffSinceLifecycleAcrossReopen(t *testing.T) {
	t1 := base
	s, dir := openTemp(t)
	mustRegister(t, s, "dev-1", "1.0")
	if _, err := s.UpdateDesired("dev-1", "op", t1, 0, json.RawMessage(`{"a":1}`)); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	// 重开后同一路径仍不同：保留首次时间。
	s2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen with diff: %v", err)
	}
	if diffs, _ := s2.Diff("dev-1"); len(diffs) != 1 || !diffs[0].Since.Equal(t1) {
		t.Fatalf("diff time must survive reopen: %+v", diffs)
	}
	// 重开后继续改值但仍不相等：沿用原时间。
	t2 := base.Add(time.Minute)
	if _, err := s2.UpdateDesired("dev-1", "op", t2, 1, json.RawMessage(`{"a":2}`)); err != nil {
		t.Fatal(err)
	}
	if diffs, _ := s2.Diff("dev-1"); !diffs[0].Since.Equal(t1) {
		t.Fatalf("persistent diff must keep original time: %+v", diffs)
	}
	// 差异消失，关闭重开：无差异、无计时记录仍合法。
	t3 := base.Add(2 * time.Minute)
	if err := s2.Report("dev-1", 1, t3, "1.0", json.RawMessage(`{"a":2}`)); err != nil {
		t.Fatal(err)
	}
	if err := s2.Close(); err != nil {
		t.Fatal(err)
	}
	s3, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen without diffs: %v", err)
	}
	if diffs, _ := s3.Diff("dev-1"); len(diffs) != 0 {
		t.Fatalf("cleared diff must stay cleared: %+v", diffs)
	}
	// 同一路径再次出现差异：必须重新计时，不能沿用消失前的 t1。
	t4 := base.Add(3 * time.Minute)
	if _, err := s3.UpdateDesired("dev-1", "op", t4, 2, json.RawMessage(`{"a":3}`)); err != nil {
		t.Fatal(err)
	}
	if err := s3.Close(); err != nil {
		t.Fatal(err)
	}
	s4, err := Open(dir)
	if err != nil {
		t.Fatalf("final reopen: %v", err)
	}
	defer s4.Close()
	diffs, _ := s4.Diff("dev-1")
	if len(diffs) != 1 || diffs[0].Path != "/a" || !diffs[0].Since.Equal(t4) {
		t.Fatalf("reappeared diff must restart timing at t4: %+v", diffs)
	}
}

package shadow

import (
	"encoding/json"
	"fmt"
	"time"
)

// 本文件集中维护修改期望配置的唯一一套业务规则，单台修改（UpdateDesired）
// 与批量修改（BatchUpdateDesired）共用，避免两处各自维护配置替换、修订号
// 递增、审计记录和差异时间更新。各入口只保留自己的参数解析、校验次序与
// 错误消息格式。

// checkDesiredMeta 校验两种修改入口共用的请求级字段：操作者非空、时间非零。
func checkDesiredMeta(operator string, at time.Time) error {
	if operator == "" {
		return ErrInvalidOperator
	}
	if at.IsZero() {
		return ErrInvalidTime
	}
	return nil
}

// checkDesiredRevision 校验调用方已读取的修订号等于设备当前修订号。
// 只校验、不改状态；失败时返回携带细节的 errDesiredRevision，由各入口
// 映射为自己公开格式的 ErrRevisionConflict。
func checkDesiredRevision(d *deviceState, deviceID string, revision uint64) error {
	if revision != d.Revision {
		return errDesiredRevision{deviceID: deviceID, current: d.Revision, given: revision}
	}
	return nil
}

// applyDesired 把一次已通过校验的修改写入影子（调用方持有 s.mu 且位于同一
// 次 commit 内）：完整替换期望配置（即使与当前相同也产生新修订）、修订号
// 加一、追加一条审计（含操作者、提交时间、新修订号、批量请求标识及修改前
// 后的完整配置，均为独立副本），并按提交时间刷新差异首次出现时间。
// requestID 在单台修改时为空。返回新修订号。
func applyDesired(d *deviceState, deviceID, operator string, at time.Time, requestID string, cfg json.RawMessage) uint64 {
	before := d.Desired
	d.Desired = cfg
	d.Revision++
	d.Audit = append(d.Audit, AuditRecord{
		DeviceID:  deviceID,
		Operator:  operator,
		Time:      at,
		Revision:  d.Revision,
		RequestID: requestID,
		Before:    cloneRaw(before),
		After:     cloneRaw(cfg),
	})
	d.refreshDiff(at)
	return d.Revision
}

// errDesiredRevision 携带统一规则判定出的修订号冲突细节。单台修改经
// desiredSingleError 映射；批量修改经 desiredBatchError 映射并带上设备标识。
type errDesiredRevision struct {
	deviceID string
	current  uint64 // 设备当前修订号
	given    uint64 // 调用方提交的已读取修订号
}

func (e errDesiredRevision) Error() string {
	return desiredSingleError(e).Error()
}

// desiredSingleError 把统一规则的冲突细节映射为单台修改公开的错误，
// 消息与既有实现保持一致。
func desiredSingleError(e errDesiredRevision) error {
	return fmt.Errorf("%w: want %d, got %d", ErrRevisionConflict, e.current, e.given)
}

// desiredBatchError 把统一规则的冲突细节映射为批量修改公开的错误，
// 消息与既有实现保持一致。
func desiredBatchError(e errDesiredRevision) error {
	return fmt.Errorf("%w: device %s want %d, got %d", ErrRevisionConflict, e.deviceID, e.current, e.given)
}

package shadow

import (
	"encoding/json"
	"fmt"
	"time"
)

// reportInput 是一次设备上报的统一输入：普通上报与安装/回滚成功附带的
// 上报共用同一结构，保证配置校验、序号判断与影子写入规则只有一处维护。
type reportInput struct {
	DeviceID string
	Seq      uint64
	At       time.Time
	Version  string
	Config   json.RawMessage
}

// reportVerdict 是一次上报按序号规则判定的结果。
type reportVerdict int

const (
	// reportAccept 表示序号更大、内容有效，必须写入影子。
	reportAccept reportVerdict = iota
	// reportDuplicate 表示相同序号且版本、发生时间、配置均一致：
	// 成功返回但不重新写入影子，尤其不改变在线状态与差异首次出现时间。
	reportDuplicate
)

// checkReport 按唯一的一套规则校验上报并给出判定：必填字段（正整数序号、
// 时间、非空版本、完整 JSON 对象配置）、可选的版本必须等于约束（安装为
// 活动目标、回滚为锁定回滚目标；空串表示不约束），以及相对已接受序号的
// 过旧/重复/冲突判断。只校验、不改状态，返回的 cfg 是配置的独立副本。
func checkReport(d *deviceState, in reportInput, requireVersion string) (cfg json.RawMessage, verdict reportVerdict, err error) {
	if in.Seq == 0 {
		return nil, 0, errBadReport{kind: reportErrSequence}
	}
	if in.At.IsZero() {
		return nil, 0, errBadReport{kind: reportErrTime}
	}
	if in.Version == "" {
		return nil, 0, errBadReport{kind: reportErrVersion}
	}
	if requireVersion != "" && in.Version != requireVersion {
		return nil, 0, errBadReport{kind: reportErrVersion}
	}
	cfg, cerr := validateConfig(in.Config)
	if cerr != nil {
		return nil, 0, errBadReport{kind: reportErrConfig}
	}
	switch {
	case in.Seq < d.LastSeq:
		return nil, 0, errBadReport{kind: reportErrStale, lastSeq: d.LastSeq, seq: in.Seq}
	case in.Seq == d.LastSeq:
		if in.Version == d.Version && in.At.Equal(d.LastReportTime) && rawEqual(cfg, d.Reported) {
			return cfg, reportDuplicate, nil
		}
		return nil, 0, errBadReport{kind: reportErrConflict, seq: in.Seq}
	}
	return cfg, reportAccept, nil
}

// applyReport 把一条已通过 checkReport 的上报写入影子（调用方持有 s.mu 且
// 位于同一次 commit 内）。重复上报原样保留影子：不重新写入、不把已被标为
// 离线的设备重新置为在线，也不刷新任何差异的首次出现时间。
func applyReport(d *deviceState, in reportInput, cfg json.RawMessage, verdict reportVerdict, at time.Time) {
	if verdict == reportDuplicate {
		return
	}
	d.Reported = cfg
	d.Version = in.Version
	d.Online = true
	d.LastSeq = in.Seq
	d.LastReportTime = at
	d.refreshDiff(at)
}

// 统一规则在校验阶段返回的错误类别；由各入口映射回自己公开的错误哨兵，
// 使普通上报与安装/回滚附带上报保持各自既有的错误类别。
type reportErrKind int

const (
	reportErrSequence reportErrKind = iota
	reportErrTime
	reportErrVersion
	reportErrConfig
	reportErrStale
	reportErrConflict
)

// errBadReport 携带统一规则判定出的错误类别。普通上报经 reportPlainError
// 映射为 ErrInvalidSequence 等；附带上报一律映射为 ErrInvalidReport。
type errBadReport struct {
	kind    reportErrKind
	lastSeq uint64
	seq     uint64
}

func (e errBadReport) Error() string {
	return reportPlainError(e).Error()
}

// reportPlainError 把统一规则的错误类别映射为普通 Report 公开的错误，
// 消息与既有实现保持一致。
func reportPlainError(e errBadReport) error {
	switch e.kind {
	case reportErrSequence:
		return ErrInvalidSequence
	case reportErrTime:
		return ErrInvalidTime
	case reportErrVersion:
		return ErrInvalidVersion
	case reportErrConfig:
		return ErrInvalidConfig
	case reportErrStale:
		return fmt.Errorf("%w: last accepted %d, got %d", ErrStaleSequence, e.lastSeq, e.seq)
	case reportErrConflict:
		return fmt.Errorf("%w: sequence %d", ErrReportConflict, e.seq)
	default:
		return ErrInvalidReport
	}
}

// reportAttachedError 把统一规则的错误类别映射为安装/回滚成功附带上报的
// 错误：任何不合规都返回 ErrInvalidReport，不改成普通上报的错误类别。
func reportAttachedError(e errBadReport) error {
	switch e.kind {
	case reportErrSequence:
		return fmt.Errorf("%w: report sequence", ErrInvalidReport)
	case reportErrTime:
		return fmt.Errorf("%w: report time", ErrInvalidReport)
	case reportErrVersion:
		return fmt.Errorf("%w: report version", ErrInvalidReport)
	case reportErrConfig:
		return fmt.Errorf("%w: config", ErrInvalidReport)
	case reportErrStale:
		return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
	case reportErrConflict:
		return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
	default:
		return ErrInvalidReport
	}
}

